import {localAnchor} from './connections.js';
import {rotate} from './fields.js';
const inverse=q=>[-q[0],-q[1],-q[2],q[3]];
export function connectedObjects(project,seeds){const adjacency=new Map();for(const c of project.connections||[])if(c.kind==='weld'&&c.b){for(const [a,b]of [[c.a,c.b],[c.b,c.a]]){if(!adjacency.has(a))adjacency.set(a,[]);adjacency.get(a).push(b);}}const result=new Set(Array.isArray(seeds)?seeds:seeds?[seeds]:[]),pending=[...result];while(pending.length){for(const id of adjacency.get(pending.pop())||[])if(!result.has(id)){result.add(id);pending.push(id);}}return [...result];}
export function createConnectivity(ids){const parents=new Map(ids.map(id=>[id,id]));const find=id=>{let root=id;while(parents.get(root)!==root)root=parents.get(root);while(id!==root){const next=parents.get(id);parents.set(id,root);id=next;}return root;};return {find,join(a,b){a=find(a);b=find(b);if(a!==b)parents.set(b,a);}};}
export function jointAnchorPairs(c,a,b,pa,pb){let anchorA=localAnchor(a,c.anchorA),anchorB=localAnchor(b,c.anchorB);if(c.preservePose){const mid=pa.p.map((v,i)=>(v+pb.p[i])/2);anchorA=rotate(mid.map((v,i)=>v-pa.p[i]),inverse(pa.q));anchorB=rotate(mid.map((v,i)=>v-pb.p[i]),inverse(pb.q));}if(c.anchorMode!=='edge')return [{a:anchorA,b:anchorB}];const axisA=c.axis||[0,0,1],axisB=c.axisB||rotate(rotate(axisA,pa.q),inverse(pb.q)),span=c.edgeSpan??.5;return [-.5,.5].map(sign=>({a:anchorA.map((v,i)=>v+axisA[i]*span*sign),b:anchorB.map((v,i)=>v+axisB[i]*span*sign)}));}
